mapper.select:
select

  distinct


from safety_build_long_confirm




  and (

    DUTY_DEPT_CODE like CONCAT(#{item},'%')

  )


  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}

select count(*) from safety_build_long_confirm




  and (

    DUTY_DEPT_CODE like CONCAT(#{item},'%')


    or EMPLOYEE_CODE = #{curEmpNo}

  )

SELECT  FROM (
select sbep.*,
       sbioh.oper_time
  from safety_build_employee_power sbep,
       safety_build_in_out_history sbioh,
       safety_employee_message sem
where sbep.EMPLOYEE_CODE = sbioh.emp_no
   and sbep.DEVICE_CODE = sbioh.device_code
   and sbep.DELETE_FLAG = 0
   and sbep.EMPLOYEE_CODE  = sem.emp_no
   and sem.status = 'NORMAL'

    and BEGIN_TIME <= now() and END_TIME > now()


     and sbioh.oper_time< #{operTimeEnd} 


    and sbep.DEVICE_CODE in

        #{item}


union all
select sbep.*, DATE_FORMAT(sbep.CREATE_TIME,'%Y-%m-%d %H:%i:%s') oper_time
  from safety_build_employee_power sbep,
       safety_employee_message sem
 where sbep.DELETE_FLAG = 0
   and sbep.EMPLOYEE_CODE  = sem.emp_no
   and sem.status = 'NORMAL'
   and NOT exists (select 1 from safety_build_in_out_history sbioh
                    where sbep.EMPLOYEE_CODE = sbioh.emp_no
                      and sbep.DEVICE_CODE = sbioh.device_code)

    and BEGIN_TIME <= now() and END_TIME > now()


   and sbep.CREATE_TIME< #{operTimeEnd} 


  and sbep.DEVICE_CODE in

    #{item}


) CUR_TMP

  order by ${orderByClause}



    limit ${offset}, ${limit}


    limit ${limit}
